&\approx 48\,\text{m/s}
\end{aligned}
$$

$v_\text{r} = \sqrt{\dfrac{mg}{k}}$, joten $$
\begin{aligned}
\dfrac{v_\text{r}'}{v_\text{r}} &= \sqrt{\dfrac{m'}{m}}
